:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --accent: #41a6f6;
  --text: #f4f4f4;
  --correct: #38b764;
  --wrong: #b13e53;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 12px;
  padding: 32px 24px;
  width: min(100%, 420px);
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

.pixel-text {
  font-family: 'Courier New', monospace;
  letter-spacing: 1px;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 16px;
  color: var(--accent);
}

.question {
  font-size: 1.4rem;
  margin: 0 0 24px;
  min-height: 2rem;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.pixel-btn {
  font-family: 'Courier New', monospace;
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--text);
  border-radius: 8px;
  padding: 12px 20px;
  cursor: pointer;
  transition: transform 0.1s, background 0.1s;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

.pixel-btn:hover { background: #6cc0ff; }
.pixel-btn:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.pixel-btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.4); }
.pixel-btn:disabled { opacity: 0.6; cursor: not-allowed; }

.answer { flex: 1; min-width: 80px; }
.answer.correct { background: var(--correct); }
.answer.wrong { background: var(--wrong); }

.score-line { margin: 0 0 24px; font-size: 1.1rem; }

.controls { display: flex; gap: 16px; justify-content: center; }
.controls .pixel-btn { flex: 1; }

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .answers { flex-direction: column; }
  .controls { flex-direction: column; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let current = 0;
let score = 0;
let answered = false;

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function render() {
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  answered = false;
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  const q = questions[current];
  const chosen = choice === 'a' ? answerA : answerB;
  if (choice === q.correct) {
    score += 1;
    scoreEl.textContent = String(score);
    chosen.classList.add('correct');
  } else {
    chosen.classList.add('wrong');
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  if (current === 0) {
    current = 1;
    render();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  scoreEl.textContent = '0';
  render();
});

render();
